bool lsp__match_doc_prefix(kobel_str prefix, kobel_str doc_mod, kobel_str doc_path) {
if (str_empty(prefix)) {
return true;
}
if ((doc_mod.len > 0) && kobel_streq(prefix, doc_mod)) {
return true;
}
if (doc_path.len > 0) {
kobel_str norm_p = str_normalize_path(prefix);
kobel_str norm_d = str_normalize_path(doc_path);
if (kobel_streq(norm_p, norm_d)) {
return true;
}
if ((norm_d.len > norm_p.len) && str_ends_with(norm_d, norm_p)) {
char sep_char = norm_d.data[((norm_d.len - norm_p.len) - 1)];
if (sep_char == '/') {
return true;
}
}
if ((norm_p.len > norm_d.len) && str_ends_with(norm_p, norm_d)) {
char sep_char = norm_p.data[((norm_p.len - norm_d.len) - 1)];
if (sep_char == '/') {
return true;
}
}
kobel_str base_p = str_base_name(norm_p);
kobel_str base_d = str_base_name(norm_d);
if (kobel_streq(base_p, base_d) && ((norm_p.len <= base_p.len) || (norm_d.len <= base_d.len))) {
return true;
}
}
return false;
}

bool lsp__is_error_for_doc(compiler__core__Diagnostic diag, kobel_str doc_mod, kobel_str doc_path) {
return lsp__match_doc_prefix(diag.file_path, doc_mod, doc_path);
}

